fn main() {
    // D4a / DESK-012：自有 command 全部经 `AppManifest::commands` 纳入 ACL。
    // Tauri 默认让自定义 command 对所有本地 webview 可用；一旦声明了 app ACL
    // manifest，未登记的 command 会被拒绝——因此本清单必须保持与
    // `src/lib.rs` 的 `generate_handler!` 逐项一致。三方（generate_handler! ↔
    // 本清单 ↔ capabilities/main-ui.json 的 allow-*）一致性由
    // `tests/workspace-structure.test.ts` 的结构门禁钉住。
    //
    // 生成物落在 `permissions/autogenerated/<command>.toml`（allow-/deny- 各一），
    // 属于不入库的衍生资产（已 gitignore），不作为 ACL 事实来源——权威是上面的
    // 三方一致门禁。tauri-build 只写不清理，本地 build 后残留的 TOML 由结构门禁
    // 在目录存在时逐项比对抓出。
    let mut attributes = tauri_build::Attributes::new();
    // Windows/MSVC：Common-Controls v6 依赖改经链接器嵌入（见函数尾部的
    // `/MANIFESTDEPENDENCY`）——tauri-build 默认把 app manifest 编进 .res 资源段，
    // 资源只链接进 bin 目标，`cargo test` 的 lib 测试二进制拿不到 manifest，
    // 会绑定 comctl32 v5（缺 v6-only 导出 `TaskDialogIndirect`），进程加载即
    // 以 0xC0000139 失败。先关掉资源段嵌入，避免 bin 目标出现双 manifest。
    let windows_msvc = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows")
        && std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    if windows_msvc {
        attributes = attributes
            .windows_attributes(tauri_build::WindowsAttributes::new_without_app_manifest());
    }
    tauri_build::try_build(
        attributes.app_manifest(tauri_build::AppManifest::new().commands(&[
            "desktop_runtime_info",
            "check_desktop_update",
            "install_desktop_update",
            "cancel_desktop_update",
            "set_provider_secret",
            "has_provider_secret",
            "delete_provider_secret",
            "save_provider_profile",
            "list_provider_profile_ids",
            "get_provider_profile",
            "delete_provider_profile",
            "validate_provider_execution_profile",
            "discover_local_ai",
            "cancel_local_ai_discovery",
            "prepare_local_ai_launch",
            "start_local_ai",
            "get_local_ai_launch_status",
            "cancel_local_ai_launch",
            "stop_local_ai",
            "stream_direct_ai",
            "stream_target_ai",
            "cancel_direct_ai",
            "save_local_card",
            "get_local_card",
            "list_local_cards",
            "delete_local_card",
            "restore_local_card",
            "purge_local_card",
            "save_local_image_asset",
            "list_local_image_assets",
            "read_local_image_asset",
            "delete_local_image_asset",
            "restore_local_image_asset",
            "purge_local_image_asset",
            "export_local_image_asset",
            "save_web_package",
            "get_web_package",
            "list_web_packages",
            "delete_web_package",
            "restore_web_package",
            "purge_web_package",
            "read_web_package_archive",
            "begin_web_package_instance",
            "append_web_package_resource",
            "open_web_package_instance",
            "control_web_package_instance",
            "begin_arena_story_pending",
            "append_arena_story_pending_part",
            "query_arena_story_pending_upload",
            "seal_arena_story_pending",
            "abort_arena_story_pending_upload",
            "describe_arena_story_pending",
            "read_arena_story_pending_chunk",
            "prepare_arena_story_pending_save",
            "save_arena_story_pending",
            "abandon_arena_story_pending",
            "begin_arena_story_pending_export",
            "advance_arena_story_pending_export",
            "end_arena_story_pending_export",
            "abort_arena_story_pending_export",
            "begin_arena_story_commit",
            "begin_arena_story_branch_commit",
            "begin_arena_story_tail_rewrite_commit",
            "append_arena_story_part",
            "end_arena_story_commit",
            "end_arena_story_branch_commit",
            "end_arena_story_tail_rewrite_commit",
            "abort_arena_story_commit",
            "query_arena_story_receipt",
            "query_arena_story_branch_receipt",
            "query_arena_story_tail_rewrite_receipt",
            "resolve_arena_story_branch_anchor",
            "resolve_arena_story_tail_rewrite_source",
            "read_magic_tea_party",
            "mutate_magic_tea_party",
            "list_arena_story_sessions",
            "delete_arena_story_session",
            "list_arena_story_chapters",
            "describe_arena_story_record",
            "read_arena_story_record_chunk",
            "read_arena_story_continue_state",
            "begin_arena_story_markdown_export",
            "append_arena_story_markdown_export",
            "end_arena_story_markdown_export",
            "abort_arena_story_markdown_export",
            "begin_local_archive_export",
            "append_local_archive_export_chunk",
            "audit_local_library",
            "create_local_backup",
            "list_local_backups",
            "prepare_local_restore",
            "exit_after_local_restore",
            "collect_local_garbage",
            "cloud_login_begin",
            "cloud_login_await",
            "cloud_login_cancel",
            "cloud_cached_account",
            "cloud_me_profile",
            "cloud_battle_reports_read",
            "cloud_arena_strict_preflight",
            "cloud_public_ranking_read",
            "cloud_save_me_profile_signature",
            "cloud_save_me_profile_avatar",
            "cloud_clear_me_profile_avatar",
            "cloud_auth_status",
            "cloud_sign_out",
            "cloud_online_status",
            "stream_hosted_ai",
            "arena_hosted_stream",
            "arena_hosted_control",
            "arena_hosted_detach",
            "arena_hosted_recovery_hint",
            "arena_room_attach",
            "arena_room_request",
            "arena_room_subscribe",
            "arena_room_detach",
            "hosted_ai_request",
            "cloud_card_library_request",
            "cloud_messages_request",
            "cancel_hosted_ai",
            "open_external_url",
            "open_cloud_account_page",
            "open_cloud_message_page",
            "announcements_get_cached",
            "announcements_refresh",
            "desktop_config_read",
            "desktop_config_write",
            "desktop_config_open_directory",
            "public_read_cache_apply_policy",
            "public_read_cache_stats",
            "public_read_cache_clear",
            "public_read_cache_query",
            "public_read_cache_card",
        ])),
    )
    .expect("failed to run tauri build script");
    if windows_msvc {
        // /MANIFESTDEPENDENCY 内联串中的空格会被链接器错解，改由
        // /MANIFESTINPUT 指向清单文件（内容与 tauri-build 默认
        // windows-app-manifest.xml 一致，见文件头注释）。
        let manifest = std::path::PathBuf::from(
            std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR should be set"),
        )
        .join("app.manifest");
        println!("cargo:rerun-if-changed={}", manifest.display());
        println!("cargo:rustc-link-arg=/MANIFEST:EMBED");
        println!("cargo:rustc-link-arg=/MANIFESTINPUT:{}", manifest.display());
    }
}
